        <footer className="details-footer">
          {isNotFound ? (
            <button type="button" className="button button-primary" onClick={close}>
              {copy.details.backToSessions}
            </button>
          ) : (
            <button type="button" className="button button-secondary" onClick={close}>
              {copy.details.close}
            </button>
          )}
        </footer>
      </div>
