                    id="cs-date"
                    type="date"
                    autoComplete="off"
                    {...inputProps("date")}
                    {...ariaFor("cs-date", {
                      error: errors.date !== undefined,
                      invalid: errors.date !== undefined || startsAtShown,
                      extra: startsAtShown ? ["cs-starts-at-error"] : [],
