                <Field id="cs-capacity" label={copy.labels.capacity} hint={copy.hints.capacity} error={errors.capacity}>
                  <div className="input-suffix">
                    <input
                      id="cs-capacity"
                      type="number"
                      inputMode="numeric"
                      autoComplete="off"
